/**
 * Convex AI hooks for use in Convex mode
 * These hooks provide AI generation capabilities using Convex actions
 *
 * IMPORTANT: These hooks require the Convex generated types.
 * Run `npx convex dev` to generate the types before using these hooks.
 */
import { useAction, useQuery } from "convex/react";

import { API_MODE } from "@/constants/api";

// @ts-ignore - Generated by `npx convex dev`
import { api } from "../../convex/_generated/api";

// Ensure we're in Convex mode
function assertConvexMode() {
  if (API_MODE !== "convex") {
    throw new Error("Convex AI hooks can only be used in Convex mode");
  }
}

/**
 * Hook for OpenAI chat
 */
export function useChat() {
  assertConvexMode();
  return useAction(api.ai.chat.chat);
}

/**
 * Hook for OpenAI chat with message history
 */
export function useSendMessage() {
  assertConvexMode();
  return useAction(api.ai.chat.sendMessage);
}

/**
 * Hook for DALL-E image generation
 */
export function useGenerateImage() {
  assertConvexMode();
  return useAction(api.ai.imageGeneration.generateImage);
}

/**
 * Hook for Replicate image generation (Flux, SDXL)
 */
export function useReplicateGenerate() {
  assertConvexMode();
  return useAction(api.ai.replicate.generate);
}

/**
 * Hook for Flux-specific image generation
 */
export function useGenerateWithFlux() {
  assertConvexMode();
  return useAction(api.ai.replicate.generateWithFlux);
}

/**
 * Hook for SDXL-specific image generation
 */
export function useGenerateWithSDXL() {
  assertConvexMode();
  return useAction(api.ai.replicate.generateWithSDXL);
}

/**
 * Hook for ElevenLabs text-to-speech
 */
export function useTextToSpeech() {
  assertConvexMode();
  return useAction(api.ai.textToSpeech.textToSpeech);
}

/**
 * Hook to get available TTS voices
 */
export function useGetAvailableVoices() {
  assertConvexMode();
  return useAction(api.ai.textToSpeech.getAvailableVoices);
}

/**
 * Hook for Whisper transcription
 */
export function useTranscribe() {
  assertConvexMode();
  return useAction(api.ai.transcription.transcribe);
}

/**
 * Hook for Whisper translation
 */
export function useTranslate() {
  assertConvexMode();
  return useAction(api.ai.transcription.translate);
}

/**
 * Hook for GPT-4 Vision image analysis
 */
export function useAnalyzeImage() {
  assertConvexMode();
  return useAction(api.ai.vision.analyzeImage);
}

/**
 * Hook to describe an image
 */
export function useDescribeImage() {
  assertConvexMode();
  return useAction(api.ai.vision.describeImage);
}

/**
 * Hook to extract text from an image (OCR)
 */
export function useExtractText() {
  assertConvexMode();
  return useAction(api.ai.vision.extractText);
}

/**
 * Hook for video generation
 */
export function useGenerateVideo() {
  assertConvexMode();
  return useAction(api.ai.video.generateVideo);
}

/**
 * Hook to check video generation status
 */
export function useCheckVideoStatus() {
  assertConvexMode();
  return useAction(api.ai.video.checkVideoStatus);
}

/**
 * Hook to get current user's credits
 */
export function useCredits() {
  assertConvexMode();
  return useQuery(api.credits.getCurrentCredits);
}

/**
 * Hook to check if user has credits
 */
export function useHasCredits() {
  assertConvexMode();
  return useQuery(api.credits.hasCredits, { amount: 1 });
}

/**
 * Hook to get user's generation history
 */
export function useGenerationHistory(limit?: number) {
  assertConvexMode();
  return useQuery(api.generations.listUserGenerations, { limit });
}

/**
 * Hook to get user's generation stats
 */
export function useGenerationStats() {
  assertConvexMode();
  return useQuery(api.generations.getUserStats);
}
